config = {"db": {"primary": {"host": "10.0.0.5", "port": 5432}}}

def lookup(data, path):
    current = data
    try:
        for key in path:
            current = current[key]
    except (KeyError, TypeError):
        return None
    return current

host = lookup(config, ["db", "primary", "host"])
missing = lookup(config, ["db", "replica", "host"])
too_deep = lookup(config, ["db", "primary", "port", "x"])
print(host, missing, too_deep)

